+	import { fetchWorkflows } from '$lib/api';
+	import { isStaticMode } from '$lib/stores/mode.svelte';
+	import { subscribe, unsubscribe, on, off } from '$lib/stores/connection.svelte';
+	import { getProjectVersion } from '$lib/stores/project.svelte';
+	import { Card, CardContent, CardHeader } from '$lib/components/ui/card';
+	import { Badge } from '$lib/components/ui/badge';
+	import { Button } from '$lib/components/ui/button';
+	import WorkflowIcon from '@lucide/svelte/icons/workflow';
+	import PlayIcon from '@lucide/svelte/icons/play';
+	import ZapIcon from '@lucide/svelte/icons/zap';
+	import RepeatIcon from '@lucide/svelte/icons/repeat';
+	import CheckCircleIcon from '@lucide/svelte/icons/check-circle';
+	import CircleDotIcon from '@lucide/svelte/icons/circle-dot';
+	import CircleIcon from '@lucide/svelte/icons/circle';
+	import CopyIcon from '@lucide/svelte/icons/copy';
+
+	// ── Data state ──
+	let workflows = $state<Workflow[]>([]);
+	let loading = $state(true);
+	let error = $state('');
+	let copiedId = $state<string | null>(null);
+
+	// ── Step type classes ──
+	const STEP_TYPE_CLASS: Record<string, string> = {
+		action: 'text-emerald-500',
+		check: 'text-blue-500',
+		decision: 'text-amber-500'
+	};
+
+	// ── Lifecycle ──
+	onMount(async () => {
+		await loadData();
+
+		if (!isStaticMode()) {
+			subscribe(['files:updates']);
+			on('files:updates', handleUpdate);
+		}
+	});
+
+	onDestroy(() => {
+		if (!isStaticMode()) {
+			off('files:updates', handleUpdate);
+			unsubscribe(['files:updates']);
+		}
+	});
+
+	// Reload on project change
+	$effect(() => {
+		const version = getProjectVersion();
+		if (version > 0) {
+			loadData();
+		}
+	});
+
+	// ── Data loading ──
+	async function loadData() {
+		try {
+			loading = true;
+			error = '';
+			const response = await fetchWorkflows();
+			workflows = response.items;
+		} catch (err) {
+			error = err instanceof Error ? err.message : 'Failed to load workflows';
+		} finally {
+			loading = false;
+		}
+	}
+
+	// ── WebSocket handler ──
+	function handleUpdate() {
+		loadData();
+	}
+
+	// ── Copy start command ──
+	async function copyStartCommand(workflowId: string) {
+		const command = `kspec workflow start @${workflowId}`;
+		try {
+			await navigator.clipboard.writeText(command);
+			copiedId = workflowId;
+			setTimeout(() => {
+				copiedId = null;
+			}, 2000);
+		} catch {
+			// Clipboard API may not be available
+		}
+	}
+</script>
