 15	test.describe('Workflows View', () => {
 16	  // AC: @ui-workflows-view ac-1
 17	  test.describe('Workflow List Rendering', () => {
 18	    test('renders workflow cards from meta definitions', async ({ page, daemon }) => {
 19	      await page.goto('/workflows');
 20	
 21	      // Wait for loading to finish
 22	      await expect(page.getByTestId('workflows-loading')).toHaveCount(0);
 23	
 24	      const workflowList = page.getByTestId('workflows-list');
 25	      await expect(workflowList).toBeVisible();
 26	
 27	      const cards = page.getByTestId('workflow-card');
 28	      await expect(cards).toHaveCount(2);
 29	    });
 30	
 31	    // AC: @ui-workflows-view ac-1 — workflow id
 32	    test('workflow card shows id', async ({ page, daemon }) => {
 33	      await page.goto('/workflows');
 34	      await expect(page.getByTestId('workflows-loading')).toHaveCount(0);
 35	
 36	      const ids = page.getByTestId('workflow-id');
 37	      await expect(ids.first()).toContainText('spec-first');
 38	      await expect(ids.nth(1)).toContainText('session-start');
 39	    });
 40	
 41	    // AC: @ui-workflows-view ac-1 — workflow description
 42	    test('workflow card shows description', async ({ page, daemon }) => {
 43	      await page.goto('/workflows');
 44	      await expect(page.getByTestId('workflows-loading')).toHaveCount(0);
 45	
 46	      const descriptions = page.getByTestId('workflow-description');
 47	      await expect(descriptions.first()).toContainText('Check spec coverage before implementing');
 48	    });
 49	
 50	    // AC: @ui-workflows-view ac-1 — trigger type badge
 51	    test('workflow card shows trigger type', async ({ page, daemon }) => {
 52	      await page.goto('/workflows');
 53	      await expect(page.getByTestId('workflows-loading')).toHaveCount(0);
 54	
 55	      const triggers = page.getByTestId('workflow-trigger');
 56	      await expect(triggers.first()).toContainText('behavior-change');
 57	      await expect(triggers.nth(1)).toContainText('session-start');
 58	    });
 59	
