  1	/**
  2	 * Export Types
  3	 *
  4	 * Types for the kspec export functionality.
  5	 * These define the structure of exported JSON snapshots and related types.
  6	 * AC: @gh-pages-export ac-2, ac-3, ac-4
  7	 */
  8	
  9	import type {
 10	  AcceptanceCriterion,
 11	  Agent,
 12	  Convention,
 13	  InboxItem,
 14	  Observation,
 15	  SessionContext,
 16	  Workflow,
 17	} from "../schema/index.js";
 18	import type { LoadedSpecItem, LoadedTask } from "../parser/yaml.js";
 19	
 20	/**
 21	 * Exported task with resolved spec reference title.
 22	 * AC: @gh-pages-export ac-3
 23	 */
 24	export interface ExportedTask extends LoadedTask {
 25	  /** Resolved title of the linked spec item (for display) */
 26	  spec_ref_title?: string;
 27	}
 28	
 29	/**
 30	 * Acceptance criterion with inheritance tracking.
 31	 * AC: @gh-pages-export ac-4
 32	 */
 33	export interface InheritedAC extends AcceptanceCriterion {
 34	  /** Reference to the trait this AC was inherited from */
 35	  _inherited_from: string;
 36	}
 37	
 38	/**
 39	 * Exported spec item with nested hierarchy and inherited ACs.
 40	 * AC: @gh-pages-export ac-4
 41	 */
 42	export interface ExportedItem extends Omit<LoadedSpecItem, 'acceptance_criteria'> {
 43	  /** Own acceptance criteria */
 44	  acceptance_criteria?: AcceptanceCriterion[];
 45	  /** Nested child items */
 46	  children?: ExportedItem[];
 47	  /** Acceptance criteria inherited from traits */
 48	  inherited_acs?: InheritedAC[];
 49	}
 50	
 51	/**
 52	 * Project metadata in the snapshot.
 53	 * AC: @gh-pages-export ac-2
 54	 */
 55	export interface ExportedProject {
 56	  name: string;
 57	  version?: string;
 58	  description?: string;
 59	}
 60	
 61	/**
 62	 * Validation result included in the snapshot.
 63	 * AC: @gh-pages-export ac-5
 64	 */
 65	export interface ExportedValidation {
 66	  valid: boolean;
 67	  errorCount: number;
 68	  warningCount: number;
 69	  errors: Array<{
 70	    file: string;
 71	    message: string;
 72	    path?: string;
 73	  }>;
 74	  warnings: Array<{
 75	    file: string;
 76	    message: string;
 77	  }>;
 78	}
 79	
 80	/**
 81	 * Full kspec snapshot structure.
 82	 * AC: @gh-pages-export ac-2
 83	 */
 84	export interface KspecSnapshot {
 85	  /** kspec version that generated this snapshot */
 86	  version: string;
 87	  /** ISO timestamp when the snapshot was exported */
 88	  exported_at: string;
 89	  /** Project metadata */
 90	  project: ExportedProject;
 91	  /** All tasks with resolved spec references */
 92	  tasks: ExportedTask[];
 93	  /** All spec items with hierarchy and inherited ACs */
 94	  items: ExportedItem[];
 95	  /** Inbox items */
 96	  inbox: InboxItem[];
 97	  /** Session context */
 98	  session: SessionContext | null;
 99	  /** Observations */
100	  observations: Observation[];
101	  /** Agents */
102	  agents: Agent[];
103	  /** Workflows */
104	  workflows: Workflow[];
105	  /** Conventions */
106	  conventions: Convention[];
107	  /** Validation results (optional) */
108	  validation?: ExportedValidation;
109	}
110	
111	/**
112	 * Options for the export command.
113	 */
114	export interface ExportOptions {
115	  /** Output format */
116	  format: 'json' | 'html';
117	  /** Output path (optional, defaults to stdout for json) */
118	  output?: string;
119	  /** Include validation results */
120	  includeValidation?: boolean;
121	  /** Dry run - show stats without writing */
122	  dryRun?: boolean;
123	}
124	
125	/**
126	 * Statistics shown during dry-run.
127	 * AC: @gh-pages-export ac-7
128	 */
129	export interface ExportStats {
130	  taskCount: number;
131	  itemCount: number;
132	  inboxCount: number;
133	  observationCount: number;
134	  agentCount: number;
135	  workflowCount: number;
136	  conventionCount: number;
137	  estimatedSizeBytes: number;
138	}

